//! Consumes an owned populated schema-40 database, generated by the previous
//! release's real model/browser/Host test. Never accepts an ordinary database.
use orange_control_plane::store::Store;
use serde_json::json;
use sqlx::Row;
use std::path::PathBuf;
#[tokio::test]
async fn migrate_populated_single_turn_database_without_replaying_effects() {
    let db = Store::connect(
        &std::env::var("ORANGE_TEST_DATABASE_URL").expect("owned pre-upgrade database"),
    )
    .await
    .expect("connect");
    let pool = db.pool();
    let name: String = sqlx::query_scalar("SELECT current_database()")
        .fetch_one(pool)
        .await
        .expect("identity");
    assert_eq!(
        name,
        std::env::var("ORANGE_CLOUD_UPGRADE_DATABASE").expect("owned id")
    );
    assert!(
        name.starts_with("orange_cloud_model_") && name.len() == "orange_cloud_model_".len() + 32
    );
    assert_eq!(
        sqlx::query_scalar::<_, i64>("SELECT max(version) FROM _sqlx_migrations WHERE success")
            .fetch_one(pool)
            .await
            .expect("old version"),
        40
    );
    let old=sqlx::query("SELECT (SELECT count(*) FROM cloud_model_proposals) AS proposals,(SELECT count(*) FROM cloud_model_quotes) AS quotes,
        (SELECT count(*) FROM cloud_model_jobs) AS jobs,(SELECT count(*) FROM cloud_model_results) AS finals,(SELECT count(*) FROM cloud_tool_responses) AS tools,
        (SELECT count(*) FROM cloud_operation_state WHERE state='unknown') AS uncertain")
        .fetch_one(pool).await.expect("prior genuine activity");
    let proposals = old.get::<i64, _>("proposals");
    let quotes = old.get::<i64, _>("quotes");
    let jobs = old.get::<i64, _>("jobs");
    let finals = old.get::<i64, _>("finals");
    let tools = old.get::<i64, _>("tools");
    let uncertain = old.get::<i64, _>("uncertain");
    assert!(proposals > 0 && quotes > 0 && jobs > 0 && finals > 0 && tools >= 3 && uncertain > 0);
    db.migrate().await.expect("apply additive turn migration");
    db.migrate().await.expect("safe repeated migration call");
    let classified=sqlx::query("SELECT (SELECT count(*) FROM cloud_model_turns WHERE ordinal=1 AND parent_operation IS NULL) AS turns,
        (SELECT count(*) FROM cloud_quote_turns) AS quotes,(SELECT count(*) FROM cloud_job_turns) AS jobs,
        (SELECT count(*) FROM cloud_model_outcomes WHERE kind='final') AS finals,(SELECT count(*) FROM cloud_model_outcomes WHERE kind='tool_request') AS tools,
        (SELECT count(*) FROM cloud_continuation_options)+(SELECT count(*) FROM cloud_continuation_intents) AS opt_ins")
        .fetch_one(pool).await.expect("backfilled records");
    assert_eq!(classified.get::<i64, _>("turns"), proposals);
    assert_eq!(classified.get::<i64, _>("quotes"), quotes);
    assert_eq!(classified.get::<i64, _>("jobs"), jobs);
    assert_eq!(classified.get::<i64, _>("finals"), finals);
    assert_eq!(classified.get::<i64, _>("tools"), tools);
    assert_eq!(classified.get::<i64, _>("opt_ins"), 0);
    let mismatches:i64=sqlx::query_scalar("SELECT count(*) FROM cloud_job_turns jt JOIN cloud_model_turns t USING(turn_id,run_id) JOIN cloud_runs r USING(run_id,owner_id)
        JOIN cloud_model_proposals p USING(run_id) JOIN jobs j USING(job_id) JOIN job_inputs i USING(job_id)
        JOIN quote_metering q ON q.quote_id=j.quote_id
        WHERE t.turn_id<>r.run_id OR t.artifact_id<>r.input_artifact_id OR t.version_id<>r.input_version_id OR t.projection_digest<>p.request_projection_digest
           OR t.invocation_id<>j.invocation_id OR j.quote_id<>jt.quote_id OR q.input_version_id<>t.version_id OR i.artifact_id<>t.artifact_id OR i.projection_digest<>t.projection_digest")
        .fetch_one(pool).await.expect("exact existing inputs and costs");
    assert_eq!(mismatches, 0);
    let actual_version: i64 =
        sqlx::query_scalar("SELECT max(version) FROM _sqlx_migrations WHERE success")
            .fetch_one(pool)
            .await
            .expect("installed schema version");
    assert!(actual_version >= 41);
    let report = json!({"old_version":40,"turn_migration":41,"new_version":actual_version,"first_turns":proposals,"quotes":quotes,"jobs":jobs,"finals":finals,"tool_requests":tools,
        "original_unknown":uncertain,"implicit_continuations":0,"mapping_mismatches":mismatches,"repeat_migration":true});
    let output = PathBuf::from(std::env::var("ORANGE_CLOUD_UPGRADE_REPORT").expect("owned report"));
    std::fs::write(output, serde_json::to_vec_pretty(&report).expect("report"))
        .expect("save receipt");
}
